import{_ as a,o,c as e,a2 as n}from"./chunks/framework.mRCPFc5l.js";const q=JSON.parse('{"title":"LLM 应用基础","description":"理解大语言模型的概率生成本质、Token 与上下文窗口、温度采样与能力边界，为上层应用打下正确的心智模型。","frontmatter":{"title":"LLM 应用基础","description":"理解大语言模型的概率生成本质、Token 与上下文窗口、温度采样与能力边界，为上层应用打下正确的心智模型。"},"headers":[],"relativePath":"ai/llm-basics.md","filePath":"ai/llm-basics.md","lastUpdated":1786263069000}'),s={name:"ai/llm-basics.md"};function l(i,t,r,d,p,u){return o(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="llm-应用基础" tabindex="-1">LLM 应用基础 <a class="header-anchor" href="#llm-应用基础" aria-label="Permalink to &quot;LLM 应用基础&quot;">​</a></h1><p>把大语言模型（LLM）当成&quot;会聊天的数据库&quot;或&quot;更聪明的搜索引擎&quot;，是大多数应用失败的起点。它既不存储事实，也不检索网页，而是一个根据上下文预测下一个 Token 的概率模型。理解这一点，才能判断哪些事该交给它、哪些不该。</p><h2 id="它本质是在预测下一个-token" tabindex="-1">它本质是在预测下一个 Token <a class="header-anchor" href="#它本质是在预测下一个-token" aria-label="Permalink to &quot;它本质是在预测下一个 Token&quot;">​</a></h2><p>模型把输入文本切成 Token，根据已见过的所有 Token，计算词表中每个候选 Token 出现的概率，挑一个接上去，再循环这个过程。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入: &quot;今天天气&quot;</span></span>
<span class="line"><span>  → 计算: 真(0.6) / 很(0.2) / 不(0.1) / ...</span></span>
<span class="line"><span>  → 选取: &quot;真&quot;</span></span>
<span class="line"><span>输入: &quot;今天天气真&quot;</span></span>
<span class="line"><span>  → 计算: 好(0.7) / 不错(0.2) / ...</span></span>
<span class="line"><span>  → 选取: &quot;好&quot;</span></span></code></pre></div><p>这个&quot;逐 Token 生成&quot;带来几个直接后果：</p><ul><li><strong>没有事实存储</strong>：它&quot;知道&quot;的东西，是训练数据在权重里留下的统计痕迹，不是可查询的记录。</li><li><strong>同一输入不同输出</strong>：每次采样带有随机性，问两遍可能得到不同答案。</li><li><strong>不可靠的计数与推理</strong>：长文本字数、列表序号、多步数学推理，常常出错，因为它在&quot;生成&quot;而非&quot;计算&quot;。</li></ul><h2 id="token-与上下文窗口" tabindex="-1">Token 与上下文窗口 <a class="header-anchor" href="#token-与上下文窗口" aria-label="Permalink to &quot;Token 与上下文窗口&quot;">​</a></h2><p>Token 是模型计费和计长度的单位，大致是&quot;一个汉字约 1-2 个 Token，一个英文单词约 1 个 Token&quot;。上下文窗口是模型一次能&quot;看见&quot;的全部文本长度上限（输入 + 输出）。</p><table tabindex="0"><thead><tr><th>概念</th><th>含义</th><th>实践影响</th></tr></thead><tbody><tr><td>输入 Token</td><td>你发给模型的 prompt 与历史</td><td>越长越贵、越慢</td></tr><tr><td>输出 Token</td><td>模型生成的回复</td><td>通常单独计价，更贵</td></tr><tr><td>上下文窗口</td><td>输入 + 输出的总上限</td><td>超出会被截断或报错</td></tr></tbody></table><p>超出窗口不是&quot;模型忘了前面&quot;，而是&quot;前面根本没被看见&quot;。塞进去的文本越多，注意力越分散，关键信息反而容易被忽略——这叫&quot;中间迷失&quot;（lost in the middle）。所以并非&quot;上下文越长越好用&quot;。</p><h2 id="温度与采样" tabindex="-1">温度与采样 <a class="header-anchor" href="#温度与采样" aria-label="Permalink to &quot;温度与采样&quot;">​</a></h2><p>温度（temperature）控制生成的随机程度：</p><ul><li><strong>温度趋近 0</strong>：几乎总是选概率最高的 Token，输出稳定、确定，适合事实问答、代码、结构化提取。</li><li><strong>温度较高（如 0.7-1.0）</strong>：概率分布被拉平，低概率 Token 也有机会被选中，输出更多样、有创造性，适合文案、头脑风暴。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>温度 0:  &quot;今天天气真好&quot;（每次几乎一样）</span></span>
<span class="line"><span>温度 0.8: &quot;今天阳光挺通透的&quot;（每次不同，但都合理）</span></span></code></pre></div><p>需要稳定可复现的场景（如提取 JSON、分类），把温度设为 0；需要发散的场景，再调高。不要用一个高温度配置去跑要求确定性的任务。</p><h2 id="能力边界-幻觉从哪里来" tabindex="-1">能力边界：幻觉从哪里来 <a class="header-anchor" href="#能力边界-幻觉从哪里来" aria-label="Permalink to &quot;能力边界：幻觉从哪里来&quot;">​</a></h2><p>幻觉（hallucination）指模型生成看起来合理但与事实不符的内容。它不是 bug，而是概率生成的必然产物：当训练数据里没有准确答案时，模型会生成&quot;统计上最像答案&quot;的文本，而不是承认不知道。</p><p>常见的不可靠场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>为什么不可靠</th></tr></thead><tbody><tr><td>具体事实、数字、日期</td><td>权重里没有精确记录，靠统计拼凑</td></tr><tr><td>引用来源、文献</td><td>会编造看起来真实的标题、作者、URL</td></tr><tr><td>严格计数与长列表</td><td>逐 Token 生成不维护内部状态</td></tr><tr><td>自我描述</td><td>不知道自己的训练数据和版本细节</td></tr></tbody></table><p>应对不是&quot;消灭幻觉&quot;，而是把它当作可管理的风险：让模型在有据可查的范围内回答（这就是 RAG 的动机），要求它给出引用，对关键输出做校验，把&quot;可能出错&quot;纳入产品设计而不是假设它一定对。</p><h2 id="上层应用的心智模型" tabindex="-1">上层应用的心智模型 <a class="header-anchor" href="#上层应用的心智模型" aria-label="Permalink to &quot;上层应用的心智模型&quot;">​</a></h2><p>理解了上述基础，再去看 Prompt、Agent、RAG，会清晰很多：</p><ul><li><strong>Prompt 工程</strong>：在固定权重下，用更好的输入引导出更可靠的输出。</li><li><strong>Agent</strong>：让模型通过&quot;调用工具&quot;绕过它不擅长的部分（计算、检索、查询），把可验证的操作交给确定性代码。</li><li><strong>RAG</strong>：把私有或最新知识塞进上下文，让模型在&quot;有据&quot;的范围内生成，减少幻觉。</li></ul><h2 id="务实的选择清单" tabindex="-1">务实的选择清单 <a class="header-anchor" href="#务实的选择清单" aria-label="Permalink to &quot;务实的选择清单&quot;">​</a></h2><ul><li>这个任务需要确定性还是创造性？据此定温度。</li><li>输入加输出会不会逼近上下文窗口？关键信息放在开头和结尾。</li><li>模型的回答是否可被外部验证？不能验证的部分不要直接面向用户做关键决策。</li><li>失败的成本多大？低成本容错场景可以大胆用，高风险场景必须加校验或人工确认。</li></ul><p>把 LLM 当成一个&quot;知识渊博但会自信地说错话、不会自己查资料&quot;的合作者，应用层的很多设计就自然落地了。</p>`,27)])])}const c=a(s,[["render",l]]);export{q as __pageData,c as default};
